fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // The minimum total distance from a point x to {x1,x2,x3}
    // is achieved by choosing x as the median of {x1,x2,x3}.
    // One can show that the resulting total distance equals max{x1,x2,x3} – min{x1,x2,x3}.
    //
    // We therefore compute the minimum and maximum of the three inputs
    // and return their difference.

    // Compute minimum of x1, x2, x3
    let mut mn = x1;
    if x2 < mn {
        mn = x2;
    }
    if x3 < mn {
        mn = x3;
    }

    // Compute maximum of x1, x2, x3
    let mut mx = x1;
    if x2 > mx {
        mx = x2;
    }
    if x3 > mx {
        mx = x3;
    }

    // The minimum total distance is mx - mn
    mx - mn
}